create extension if not exists pgcrypto;
create table if not exists menu_admin_profiles(user_id uuid primary key references auth.users(id) on delete cascade,username text unique not null,must_change_password boolean not null default true,created_at timestamptz not null default now());
create table if not exists menu_categories(id uuid primary key default gen_random_uuid(),name text not null,available boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now());
create table if not exists menu_products(id uuid primary key default gen_random_uuid(),category_id uuid references menu_categories(id),raffinato_product_id int,name text not null,description text not null default '',price numeric(12,2) not null check(price>=0),image_url text,available boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now());
create table if not exists menu_cards(id uuid primary key default gen_random_uuid(),label text unique not null,virtual_code text unique not null,available boolean not null default true,sort_order int not null default 0);
create table if not exists menu_references(id uuid primary key default gen_random_uuid(),name text unique not null,available boolean not null default true,sort_order int not null default 0);
create table if not exists menu_settings(id boolean primary key default true check(id),ordering_enabled boolean not null default false,test_validated boolean not null default false);
insert into menu_settings(id) values(true) on conflict do nothing;
create table if not exists menu_integration(id boolean primary key default true check(id),endpoint_url text,http_method text,auth_type text,notes text,updated_at timestamptz not null default now());
insert into menu_integration(id) values(true) on conflict do nothing;
create table if not exists menu_orders(id uuid primary key default gen_random_uuid(),guid uuid unique not null,card_id uuid references menu_cards(id),card_label text not null,reference_id uuid references menu_references(id),reference_name text not null,note text,status text not null default 'pending',request_payload jsonb,response_payload jsonb,http_status int,idvenda text,numeropedido text,error_message text,created_at timestamptz not null default now(),sent_at timestamptz);
create table if not exists menu_order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references menu_orders(id) on delete cascade,product_id uuid references menu_products(id),raffinato_product_id int,name text not null,quantity numeric(12,3) not null,unit_price numeric(12,2) not null);
alter table menu_admin_profiles enable row level security;alter table menu_categories enable row level security;alter table menu_products enable row level security;alter table menu_cards enable row level security;alter table menu_references enable row level security;alter table menu_settings enable row level security;alter table menu_integration enable row level security;alter table menu_orders enable row level security;alter table menu_order_items enable row level security;
revoke all on all tables in schema public from anon,authenticated;
